'use strict';

// MODULES //

var tape = require( 'tape' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var isEqualInt64Array = require( '@stdlib/assert/is-equal-int64array' );
var isFunction = require( '@stdlib/assert/is-function' );
var instanceOf = require( '@stdlib/assert/instance-of' );
var Number = require( '@stdlib/number/ctor' );
var Int64Array = require( './../lib' );


// FUNCTIONS //

/**
* Comparison function for sorting in descending order.
*
* @private
* @param {Int64} a - first value for comparison
* @param {Int64} b - second value for comparison
* @returns {number} comparison result
*/
function compareFcn( a, b ) {
	return Number( b ) - Number( a );
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Int64Array, 'function', 'main export is a function' );
	t.end();
});

tape( 'attached to the prototype of the main export is a `toSorted` method', function test( t ) {
	t.strictEqual( hasOwnProp( Int64Array.prototype, 'toSorted' ), true, 'has property' );
	t.strictEqual( isFunction( Int64Array.prototype.toSorted ), true, 'has method' );
	t.end();
});

tape( 'the method throws an error if invoked with a `this` context which is not a 64-bit signed integer array instance', function test( t ) {
	var values;
	var arr;
	var i;

	arr = new Int64Array( 5 );

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return arr.toSorted.call( value, compareFcn );
		};
	}
});

tape( 'the method throws an error if provided a first argument which is not a function', function test( t ) {
	var values;
	var arr;
	var i;

	arr = new Int64Array( 10 );

	values = [
		'5',
		3.14,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[]
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return arr.toSorted( value );
		};
	}
});

tape( 'the method returns an empty array if operating on an empty 64-bit signed integer array', function test( t ) {
	var arr;
	var out;

	arr = new Int64Array();
	out = arr.toSorted( compareFcn );

	t.strictEqual( out.length, 0, 'returns expected value' );
	t.end();
});

tape( 'the method returns a new typed array containing elements in sorted order', function test( t ) {
	var expected;
	var arr;
	var out;

	arr = new Int64Array( [ 3, -1, 5, -2, 4 ] );
	expected = new Int64Array( [ 5, 4, 3, -1, -2 ] );
	out = arr.toSorted( compareFcn );

	t.strictEqual( instanceOf( out, Int64Array ), true, 'returns expected value' );
	t.notEqual( out, arr, 'returns a new instance' );
	t.strictEqual( isEqualInt64Array( out, expected ), true, 'returns expected value' );
	t.end();
});

tape( 'if not provided a comparison function, the method returns a new typed array containing elements in ascending order', function test( t ) {
	var expected;
	var arr;
	var out;

	arr = new Int64Array( [ 3, -1, 5, -2, 4 ] );
	expected = new Int64Array( [ -2, -1, 3, 4, 5 ] );
	out = arr.toSorted();

	t.strictEqual( instanceOf( out, Int64Array ), true, 'returns expected value' );
	t.notEqual( out, arr, 'returns a new instance' );
	t.strictEqual( isEqualInt64Array( out, expected ), true, 'returns expected value' );
	t.end();
});

tape( 'the method does not change the array length', function test( t ) {
	var arr;
	var out;

	arr = new Int64Array( [ 3, -1, 5, -2, 4 ] );
	out = arr.toSorted( compareFcn );

	t.strictEqual( out.length, arr.length, 'returns expected value' );
	t.end();
});
